conditions.value_template:
{% set room_temp = states('sensor.temperatura_camera_carlo') | float(none) %}
{% set target = state_attr('climate.trv_vtherm_camera_carlo', 'temperature') | float(none) %}
{% set now_ts = as_timestamp(now()) %}
{% set sensor_age = now_ts - as_timestamp(states['sensor.temperatura_camera_carlo'].last_reported, 0) %}
{% set c = states('input_text.camera_carlo_pdc_ciclo') | from_json({}) %}
{% set c = c if c is mapping else {} %}
{% set started = c.get('on') | float(none) %}
{% set start_target = c.get('target') | float(none) %}
{% set elapsed = now_ts - started if started is not none else none %}
{% set minimum_done = c.get('m') == 'heat' and elapsed is not none and elapsed >= 600 %}
{% set lowered_target = target is not none and start_target is not none and target < start_target and room_temp is not none and room_temp >= target %}
{{ room_temp is not none and target is not none and 0 <= sensor_age <= 3600
   and (room_temp >= target + 0.5 - 0.000001
        or (minimum_done and room_temp >= target + 0.2 - 0.000001)
        or lowered_target) }}
